{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Thalidomide, the closest structural analogue sharing the 3-substituted piperidine-2,6-dione and imide/lactam system, has an absolute oral bioavailability of 80–100% in fasting healthy volunteers, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "(S)-Thalidomide, a direct enantiomeric analogue of the query scaffold, showed an absolute oral bioavailability of approximately 80% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "(R)-Thalidomide showed an absolute oral bioavailability of approximately 100% in healthy volunteers, providing additional high-bioavailability evidence for the same structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Aminoglutethimide, another oral glutarimide drug bearing an aniline substituent, has an oral bioavailability of approximately 100%, supporting high F despite lower structural similarity.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The closest and most transferable evidence, thalidomide and its enantiomers, demonstrates high absolute oral bioavailability (80–100%) in humans. The query shares the critical glutarimide/isoindolinone scaffold, so F ≥20% is strongly supported. No relevant low-bioavailability evidence outweighs this.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is present; prediction relies on close thalidomide analogues.",
    "The query's 4-amino and reduced isoindolinone modifications could alter solubility or transporter behavior, but available analogues do not suggest a low-F liability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

